namespace sv_9d47faa678414678874a5bdf673e3010.Services;

public class WarehouseInfo
{
    public required string Id { get; init; }
    public required string Name { get; init; }
}

/// <summary>
/// Scoped service (per-circuit) that holds the currently selected warehouse
/// and notifies subscribers when it changes.
/// </summary>
public class WarehouseStateService
{
    private static readonly List<WarehouseInfo> _allWarehouses =
    [
        new() { Id = "WH-001", Name = "Warehouse A — East" },
        new() { Id = "WH-002", Name = "Warehouse B — West" },
        new() { Id = "WH-003", Name = "Warehouse C — Central" },
    ];

    public IReadOnlyList<WarehouseInfo> Warehouses => _allWarehouses;

    public WarehouseInfo CurrentWarehouse { get; private set; } = _allWarehouses[0];

    public event Func<Task>? OnChange;

    public async Task SetWarehouseAsync(string warehouseId)
    {
        var warehouse = _allWarehouses.FirstOrDefault(w => w.Id == warehouseId);
        if (warehouse is null || warehouse.Id == CurrentWarehouse.Id)
            return;

        CurrentWarehouse = warehouse;

        if (OnChange is not null)
            await OnChange.Invoke();
    }
}

namespace sv_9d47faa678414678874a5bdf673e3010.Services;

/// <summary>
/// Scoped service (per-circuit) that manages low-stock alert polling
/// and broadcasts new counts to all subscribed components.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int CurrentAlertCount { get; private set; }

    /// <summary>
    /// Fired whenever a new alert count is fetched. All subscribed components
    /// receive the notification regardless of which one triggered the poll.
    /// </summary>
    public event Func<Task>? OnAlertCountChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChangedAsync;
    }

    /// <summary>Simulates a database query returning low-stock item count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Registers a subscriber. Polling starts when the first subscriber registers.
    /// Call <see cref="Unsubscribe"/> when the component is disposed.
    /// </summary>
    public async Task Subscribe()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
            await StartPollingAsync();
    }

    public void Unsubscribe()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
            StopPolling();
    }

    private async Task StartPollingAsync()
    {
        StopPolling();

        // Fetch immediately on start
        await RefreshAlertCountAsync();

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        _ = Task.Run(async () =>
        {
            try
            {
                while (await _timer.WaitForNextTickAsync(_cts.Token))
                {
                    await RefreshAlertCountAsync();
                }
            }
            catch (OperationCanceledException)
            {
                // Expected on stop
            }
        });
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    private async Task RefreshAlertCountAsync()
    {
        CurrentAlertCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouse.Id);

        if (OnAlertCountChanged is not null)
            await OnAlertCountChanged.Invoke();
    }

    private async Task HandleWarehouseChangedAsync()
    {
        if (_subscriberCount > 0)
            await RefreshAlertCountAsync();
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChangedAsync;
        StopPolling();
    }
}

