namespace sv_9d47faa678414678874a5bdf673e3010.Services;

public class WarehouseInfo
{
    public required string Id { get; init; }
    public required string Name { get; init; }
}

/// <summary>
/// Scoped service (per-circuit) that holds the currently selected warehouse
/// and notifies subscribers when it changes.
/// </summary>
public class WarehouseStateService
{
    private static readonly List<WarehouseInfo> _allWarehouses =
    [
        new() { Id = "WH-001", Name = "Warehouse A — East" },
        new() { Id = "WH-002", Name = "Warehouse B — West" },
        new() { Id = "WH-003", Name = "Warehouse C — Central" },
    ];

    public IReadOnlyList<WarehouseInfo> Warehouses => _allWarehouses;

    public WarehouseInfo CurrentWarehouse { get; private set; } = _allWarehouses[0];

    public event Func<Task>? OnChange;

    public async Task SetWarehouseAsync(string warehouseId)
    {
        var warehouse = _allWarehouses.FirstOrDefault(w => w.Id == warehouseId);
        if (warehouse is null || warehouse.Id == CurrentWarehouse.Id)
            return;

        CurrentWarehouse = warehouse;

        if (OnChange is not null)
            await OnChange.Invoke();
    }
}

