@using sv_9d47faa678414678874a5bdf673e3010.Services
@rendermode InteractiveServer
@implements IDisposable
@inject WarehouseStateService WarehouseState

<div class="warehouse-selector">
    <label for="warehouse-select" class="form-label mb-0 me-2 text-nowrap">Warehouse:</label>
    <select id="warehouse-select"
            class="form-select form-select-sm"
            value="@WarehouseState.CurrentWarehouse.Id"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseState.Warehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChanged;
    }

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
            await WarehouseState.SetWarehouseAsync(id);
    }

    private async Task HandleStateChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChanged;
    }
}

