@page "/dashboard"
@using sv_9d47faa678414678874a5bdf673e3010.Services
@rendermode InteractiveServer
@implements IDisposable
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">@WarehouseState.CurrentWarehouse.Name</p>
                <p class="text-muted">ID: @WarehouseState.CurrentWarehouse.Id</p>
            </div>
        </div>
    </div>
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="card-text">
                    <span class="fs-1 fw-bold @AlertTextClass">@AlertService.CurrentAlertCount</span>
                    <span class="ms-2 text-muted">items below minimum level</span>
                </p>
                <p class="text-muted"><small>Auto-refreshes every 10 seconds</small></p>
            </div>
        </div>
    </div>
</div>

@code {
    private string AlertTextClass =>
        AlertService.CurrentAlertCount > 0 ? "text-danger" : "text-success";

    protected override async Task OnInitializedAsync()
    {
        WarehouseState.OnChange += HandleStateChanged;
        AlertService.OnAlertCountChanged += HandleAlertChanged;

        // Start polling when dashboard becomes visible
        await AlertService.Subscribe();
    }

    private async Task HandleStateChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    private async Task HandleAlertChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChanged;
        AlertService.OnAlertCountChanged -= HandleAlertChanged;

        // Stop polling when user leaves the dashboard
        AlertService.Unsubscribe();
    }
}

